void Solver::bump_var(int var, double coeff) {
    // Dynamic coefficient adjustment based on variable activity and level
    double dynamic_coeff = coeff;
    if (level[var] > 0) {
        // Reward variables involved in high-level conflicts more aggressively
        dynamic_coeff *= (1.0 + 0.01 * level[var]);
    }
    // Update activity with overflow protection
    activity[var] += var_inc * dynamic_coeff;
    if (activity[var] > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    // Update heap if present
    if (vsids.inHeap(var)) vsids.update(var);
}
